#!/usr/bin/env python3
from pathlib import Path
import json
H=Path(__file__).resolve().parent
P='https://mail.dabas.hu/images/stories/Letoltesek/onkormanyzat009.pdf'
T='https://mail.dabas.hu/images/stories/Varosunk/DabasTerkep2015k.pdf'
rows=[
('Alsódabas',[[19.3020,47.1874],[19.3097,47.1891],[19.3166,47.1900],[19.3228,47.1914],[19.3305,47.1934],[19.3360,47.1877],[19.3423,47.1836],[19.3478,47.1799],[19.3390,47.1767],[19.3300,47.1758],[19.3200,47.1747],[19.3104,47.1765],[19.3052,47.1815]],['Kossuth László utca / Szent István út northern historical transition','Bartók Béla út and civic center','route 5 northeastern edge','Vörösmarty utca','Határ utca southern transition','Rét utca / Tölgyfa utca western fringe'],[P,T,'https://www.dabas.hu/index.php/varosunk/idegenforgalom/latnivalok'],'Whole continuous historical quarter estimate around Szent István út and the kúria/street network, including the later civic center. The strategy places the Dabas/Gyón transition at Határ út and describes the Kossuth László–Klapka section as the kúria district. Its transition toward Felsődabas is inferred from street character, not established as a legal historical line; overlap with Városközpont and Felsődabas is intentional.'),
('Felsődabas',[[19.2875,47.1980],[19.2935,47.1997],[19.2988,47.2007],[19.3063,47.1989],[19.3126,47.1967],[19.3168,47.1936],[19.3182,47.1901],[19.3134,47.1872],[19.3094,47.1857],[19.3033,47.1830],[19.2972,47.1850],[19.2926,47.1891],[19.2892,47.1930]],['Tulipán utca northern division toward Sári','Fő út','József Attila utca','Vásártér utca / Dabasi Vásártér','Bem utca','XXVII. csatorna eastern vicinity','Bercsényi utca / Templom utca','Kossuth László utca southern transition'],[P,T,'https://dabas.hu/index.php/onkormanyzat/teb-ertektar/teb-nyilvantartas/utmenti-keresztjeink'],'Broad historical village-quarter envelope from the Tulipán/Sári transition through Fő út, the market and József Attila/Bem street fabric. The primary strategy supplies the Tulipán outer division but no surveyed internal Felsődabas/Alsódabas border. The southern transition and field-edge connectors are inferred and can overlap the adjacent historical quarter.'),
('Gyón',[[19.3144,47.1740],[19.3205,47.1750],[19.3290,47.1773],[19.3366,47.1789],[19.3448,47.1819],[19.3529,47.1844],[19.3584,47.1816],[19.3679,47.1748],[19.3770,47.1680],[19.3715,47.1614],[19.3700,47.1564],[19.3634,47.1519],[19.3510,47.1464],[19.3370,47.1493],[19.3310,47.1543],[19.3260,47.1590],[19.3200,47.1638],[19.3140,47.1676]],['Határ utca northern division','Kossuth Lajos út','Vasút út and Luther utca historical center','route 5 northeastern edge','Vacsi út','Rabárerdő út','Örkényi út','Tatárszentgyörgyi út','Szélmalom utca','Gödör utca / western turján fringe'],[P,T],'Whole main Gyón settlement-body estimate, retaining its broad northeastern street grid, historical core, southwestern recreation/cemetery fringe and southeastern dispersed development. The municipal strategy explicitly identifies Határ út, the Vasút/Luther core, Vacsi route and the Rabárerdő/Örkényi expansion. Outer field/woodland connectors are rough. Detached Dabasi-Szőlők has its own prior polygon and is not blindly merged into this main-body geometry.'),
('Sári',[[19.2604,47.2266],[19.2654,47.2229],[19.2695,47.2202],[19.2741,47.2196],[19.2788,47.2167],[19.2826,47.2131],[19.2887,47.2092],[19.2905,47.2050],[19.2949,47.2030],[19.2953,47.2001],[19.2900,47.1983],[19.2849,47.2000],[19.2781,47.2036],[19.2741,47.2074],[19.2694,47.2105],[19.2638,47.2112],[19.2592,47.2131],[19.2608,47.2161],[19.2610,47.2184],[19.2651,47.2193]],['Tulipán utca southeastern division toward Felsődabas','Szent János út','Tabáni út','Hajcsár utca','Duna-völgyi-főcsatorna southwestern edge','route 5 northeastern edge','Mánteleki utca','Rákóczi utca','industrial-park edge northwest'],[P,T,'https://dabas.hu/index.php/onkormanyzat/teb-ertektar/teb-nyilvantartas/utmenti-keresztjeink'],'Whole main Sári village-quarter envelope including the Tabáni–Hajcsár historical core and later Szent János/Rákóczi streets to Tulipán utca. The primary strategy describes the canal/woodland/industrial-park setting and the Tulipán division. Western canal bends and eastern route-5 fringe guide the rough ring. Detached Besnyő and the separately named Páskom locality remain distinct; this is not the whole combined Sári–Besnyő service district.'),
('Városközpont',[[19.3135,47.1867],[19.3147,47.1893],[19.3162,47.1917],[19.3208,47.1942],[19.3260,47.1941],[19.3310,47.1927],[19.3321,47.1902],[19.3355,47.1882],[19.3320,47.1862],[19.3290,47.1844],[19.3242,47.1827],[19.3191,47.1832],[19.3163,47.1858]],['Bartók Béla út civic/commercial corridor','Szent István tér','Iskola utca','Sportcsarnok utca','Meder utca / Pesti út northern edge','railway / route 5 northeastern vicinity','Piac utca','Kert utca','Zlinszky utca','Klapka utca southern vicinity'],[P,T],'Functional city-center quarter around the complete civic/commercial corridor, schools, health care, arena, market, memorial and Jubilee parks, rather than one civic building or plaza. Municipal sources locate the center along Bartók Béla toward route 5 and name those institutions. Outer residential-block and transport-edge joins are inferred. This later functional quarter overlaps historical Alsódabas.'),
('Mántelek',[[19.2350,47.1955],[19.2444,47.1960],[19.2504,47.1931],[19.2550,47.1870],[19.2622,47.1810],[19.2660,47.1760],[19.2580,47.1700],[19.2470,47.1670],[19.2405,47.1730],[19.2364,47.1810],[19.2320,47.1900]],['Mánteleki út access spine','Mántelek manor/hamlet street and farmyard group','Mántelek Kastély southern cluster','Mánteleki Horgásztó northwestern cluster','XX. csatorna eastern boundary vicinity','mapped western field tracks','southern manor access tracks'],['https://mail.dabas.hu/images/stories/Varosunk/Dabas_egeszseghaz_partnersegi_250711_VEGLEGES.pdf',T,'https://www.proba.dabas.hu/index.php/onkormanyzat/teb-ertektar/teb-nyilvantartas/dr-nemes-janos-grof-felsodabasi-uradalmanak-gazdalkodasa-a-ket-vilaghaboru-kozotti-idoszakban','https://mapcarta.com/N11983061935'],'Broad hamlet/manor locality estimate incorporating the inhabited/farm groups, manor access and the named Mánteleki lake surroundings. The municipal planning text recognizes Mántelek as a historical detached settlement; source road/landuse/water geometries locate its full cluster and countryside setting. This is much broader than the individual manor building, farmyard or lake surface. Perimeter tracks, canal and adjoining field edges are approximate; the complete former landed estate and old jurisdiction are not established.'),
('Páskom',[[19.2602,47.2097],[19.2655,47.2105],[19.2702,47.2068],[19.2751,47.2038],[19.2789,47.1994],[19.2743,47.1961],[19.2686,47.1938],[19.2612,47.1932],[19.2568,47.1968],[19.2560,47.2011],[19.2587,47.2057]],['Mánteleki út pasture/industrial/farm corridor','XX. árapasztó channel western side','mapped Sári outer pasture field tracks','Dabasi-csatorna southern vicinity','eastern field access tracks toward Sári'],['https://www.dabas.hu/images/stories/Hivatal/hesz/DABAS_TSZT_leiras_velemenyezesi_2021_10.pdf','https://archive.pestvarmegye.hu/ertektar/4122-az-elso-szines-jatekfilm-pest-megyei-forgatasa-dabas',T],'Historical Sári-edge pasture/locality estimate around the Mánteleki road corridor, incorporating present industrial/farm groups and surrounding fields rather than just their footprints. The municipal planning index separately names Páskom and the county heritage account describes the Sári-edge Páskom pasture. Actual channels and field-access roads anchor the rough envelope. Páskom utca in the residential village is supporting toponymy, not asserted to be this whole locality or used as an alias.'),
('Öregországút',[[19.3290,47.2147],[19.3320,47.2121],[19.3350,47.2091],[19.3405,47.2060],[19.3450,47.2038],[19.3500,47.2011],[19.3546,47.1983],[19.3501,47.1977],[19.3457,47.2002],[19.3410,47.2025],[19.3360,47.2044],[19.3315,47.2079],[19.3280,47.2115]],['Öregországút former-road settlement spine','Szabadság út / Juhar utca southern junction','railway western vicinity','mapped lateral farm access roads','field edges beside the old road north of Szabadság út'],[P,T,'https://mail.proba.dabas.hu/index.php/onkormanyzat/kozbeszerzesek/ivovizminoseg-javitasa/hirek-aktualitasok'],'Estimated former-road hamlet corridor around the identified northern Dabas locality. The municipal strategy describes a small separate settlement along the former highway; infrastructure evidence links the old road to Szabadság út and Szőlőhegyi access. The ring follows the actual bent road alignment and adjacent mapped access/field pattern. Its width and northern/southern residential transitions are inferred; the full interurban road is not the neighborhood boundary.')]
areas=[]
for n,r,a,u,note in rows:
 if r[-1]!=r[0]:r.append(r[0])
 areas.append({'municipality':'Dabas','name':n,'ring':r,'anchors':a,'urls':u,'note':note})
(H/'manual-traces.json').write_text(json.dumps({'areas':areas},ensure_ascii=False,indent=2)+'\n')
